-- Phase L follow-up: complete recurring cron advancement and atomic worker claiming.
create or replace function public.cron_field_matches(field text,value integer) returns boolean language plpgsql immutable as $$ declare part text; a integer; b integer; step integer; base text; begin if field='*' then return true; end if; foreach part in array string_to_array(field,',') loop step:=1; if position('/' in part)>0 then base:=split_part(part,'/',1); step:=split_part(part,'/',2)::integer; else base:=part; end if; if base='*' then a:=0; b:=59; elsif position('-' in base)>0 then a:=split_part(base,'-',1)::integer; b:=split_part(base,'-',2)::integer; else a:=base::integer; b:=a; end if; if value>=a and value<=b and mod(value-a,step)=0 then return true; end if; end loop; return false; end; $$;
create or replace function public.next_cron_run(p_expr text,p_after timestamptz,p_timezone text default 'UTC') returns timestamptz language plpgsql immutable as $$ declare f text[]; cur timestamptz; local timestamp; i integer; begin f:=regexp_split_to_array(trim(p_expr),'\\s+'); if array_length(f,1)<>5 then return null; end if; cur:=date_trunc('minute',p_after)+interval '1 minute'; for i in 0..527039 loop local:=cur at time zone p_timezone; if public.cron_field_matches(f[1],extract(minute from local)::integer) and public.cron_field_matches(f[2],extract(hour from local)::integer) and public.cron_field_matches(f[3],extract(day from local)::integer) and public.cron_field_matches(f[4],extract(month from local)::integer) and public.cron_field_matches(f[5],extract(isodow from local)::integer) then return cur; end if; cur:=cur+interval '1 minute'; end loop; return null; end; $$;
revoke all on function public.cron_field_matches(text,integer) from public,anon,authenticated; revoke all on function public.next_cron_run(text,timestamptz,text) from public,anon,authenticated;
create or replace function public.claim_due_schedules(p_limit integer default 10,p_lease_seconds integer default 120) returns setof public.scheduled_runs language plpgsql security definer set search_path=public as $$ declare r record; v_run public.scheduled_runs; v_next timestamptz; begin for r in select * from public.schedules where enabled and next_run_at is not null and next_run_at<=now() order by next_run_at asc for update skip locked limit greatest(1,least(p_limit,50)) loop insert into public.scheduled_runs(schedule_id,owner_id,status,scheduled_for,max_attempts,payload,idempotency_key,lease_token,lease_expires_at,started_at) values(r.id,r.owner_id,'running',r.next_run_at,3,r.payload,to_char(r.next_run_at at time zone 'UTC','YYYYMMDDHH24MISSMSOF'),gen_random_uuid(),now()+make_interval(secs=>greatest(30,least(p_lease_seconds,900))),now()) on conflict(schedule_id,idempotency_key) do nothing returning * into v_run; if v_run.id is not null then v_next:=case when r.schedule_kind='once' then null when r.schedule_kind='interval' and r.schedule_expression ~ '^\\d+$' then greatest(r.next_run_at+(r.schedule_expression::integer*interval '1 second'),now()+interval '1 second') when r.schedule_kind='cron' then public.next_cron_run(r.schedule_expression,r.next_run_at,r.timezone) else null end; update public.schedules set last_run_at=v_run.scheduled_for,last_run_id=v_run.id,next_run_at=v_next,enabled=case when v_next is null then false else enabled end,updated_at=now() where id=r.id; return next v_run; end if; end loop; return; end; $$; revoke all on function public.claim_due_schedules(integer,integer) from public,anon,authenticated;
